Cho hình vẽ biết $\widehat { A _{1} }=58^{\circ}$, $\widehat { B _{3} }=122^{\circ}$ hỏi hai đường thẳng ${n}$ và ${m}$ có song song với nhau không? tính số đo các góc còn lại.
}{
\begin{tikzpicture}
            \coordinate (E) at (1.14, 3.06);
            \coordinate (D) at (4.46, 0);
            \coordinate (C) at (-0.6, 0);
            \coordinate (B) at (5, 2);
            \coordinate (A) at (0, 2);
            \coordinate (F) at (3.6, -1.44);
            \coordinate (H) at (2.81, 0);
            \coordinate (G) at (1.72, 2);
            % Vẽ tứ giác
            \draw[thick] (C) -- (H)--(D);
            \draw[thick] (A) -- (G) -- (B);
            \draw[thick] (E) -- (G) -- (H)--(F);
            % Ghi nhãn các điểm

            \node[above] at (G) {$A $};
            \node[above ] at (H){$B $};
                      \node[above] at (A) {$n$};
                        \node[above] at (C) {$m$};
            \draw 
            (G) node[shift={(-25:15pt)}]{$1$}  ;
            \draw (G) node[shift={(30:11pt)}]{$2$};
            \draw  (G) node[shift={(50:-15pt)}]{$3$}  ;
            \draw (G)  node[shift={(-25:-15pt)}]{$4$};  

            \draw (H) node[shift={(-25:15pt)}]{$1$};
            \draw (H) node[shift={(40:15pt)}]{$2$}  ;
            \draw  (H) node[shift={(50:-13pt)}]{$3$} ;
            \draw (H) node[shift={(-25:-15pt)}]{$4$}  ;     
        \end{tikzpicture}
}
\loigiai{
Vì $\widehat{ B _{4} } = 180^{\circ}-\widehat { B _{3} }= 58^{\circ}$ suy ra $\widehat { A _{1} }=\widehat{ B _{4} } $ mà hai góc so le trong nên $n //m$ .\\
$\widehat { A _{4} }=\widehat{ B _{1} }=\widehat{ A _{1} }= \widehat{ B _{4} }=58^{\circ}$\\
$\widehat { A _{2} }= \widehat{ B _{3} }=\widehat{ A _{3} }=\widehat{  B _{2} }=122^{\circ}$
}\end{ex}

